/*
 * Edit only the CONFIG object when adapting this template.
 *
 * Important:
 * - The Actor accepts exactly one public channel username per run.
 * - Use usernames only: no @ prefix, t.me URL, invite link, or private channel.
 * - An empty keywords array alerts on every unseen post returned in the polling window.
 * - firstRunMode "baseline" suppresses the initial result window.
 */
const CONFIG = {
  channels: [
    'telegram',
    'durov',
  ],
  actorId: 'txAD7J0iGSmiy7Kgp',
  actorBuild: '0.0.4',
  limit: 5,
  actorMemoryMb: 128,
  actorTimeoutSeconds: 120,
  firstRunMode: 'baseline', // "baseline" or deliberate opt-in "alert"
  keywordMode: 'any', // "any", "all", or "off"
  keywords: [],
  caseSensitive: false,
  alertChatId: 'REPLACE_WITH_TELEGRAM_CHAT_ID',
  maxAlertTextChars: 3000,
};

const usernamePattern = /^[A-Za-z][A-Za-z0-9_]{4,31}$/;
const normalizedChannels = [];
const duplicateGuard = new Set();

if (!Array.isArray(CONFIG.channels)) {
  throw new Error('CONFIG.channels must be an array of public channel usernames.');
}

for (const rawChannel of CONFIG.channels) {
  const channel = String(rawChannel ?? '').trim();
  if (!usernamePattern.test(channel)) {
    throw new Error(
      `Invalid public Telegram channel username "${channel}". ` +
      'Use the username only, without @ or a URL.',
    );
  }

  const stateKey = channel.toLowerCase();
  if (duplicateGuard.has(stateKey)) continue;
  duplicateGuard.add(stateKey);
  normalizedChannels.push(channel);
}

if (normalizedChannels.length === 0) {
  throw new Error('CONFIG.channels must contain at least one valid public channel username.');
}

if (!Number.isInteger(CONFIG.limit) || CONFIG.limit < 1 || CONFIG.limit > 500) {
  throw new Error('CONFIG.limit must be an integer from 1 to 500.');
}

if (
  !Number.isInteger(CONFIG.actorMemoryMb) ||
  CONFIG.actorMemoryMb < 128 ||
  CONFIG.actorMemoryMb > 512
) {
  throw new Error('CONFIG.actorMemoryMb must be an integer from 128 to 512.');
}

if (
  !Number.isInteger(CONFIG.actorTimeoutSeconds) ||
  CONFIG.actorTimeoutSeconds < 1 ||
  CONFIG.actorTimeoutSeconds > 3600
) {
  throw new Error('CONFIG.actorTimeoutSeconds must be an integer from 1 to 3600.');
}

if (!['baseline', 'alert'].includes(CONFIG.firstRunMode)) {
  throw new Error('CONFIG.firstRunMode must be "baseline" or "alert".');
}

if (!['any', 'all', 'off'].includes(CONFIG.keywordMode)) {
  throw new Error('CONFIG.keywordMode must be "any", "all", or "off".');
}

if (!Array.isArray(CONFIG.keywords) || !CONFIG.keywords.every(
  (keyword) => typeof keyword === 'string',
)) {
  throw new Error('CONFIG.keywords must be an array of strings.');
}

if (typeof CONFIG.caseSensitive !== 'boolean') {
  throw new Error('CONFIG.caseSensitive must be true or false.');
}

const alertChatId = String(CONFIG.alertChatId ?? '').trim();
if (!alertChatId || alertChatId === 'REPLACE_WITH_TELEGRAM_CHAT_ID') {
  throw new Error(
    'Replace CONFIG.alertChatId with the Telegram destination before activation.',
  );
}

if (
  !Number.isInteger(CONFIG.maxAlertTextChars) ||
  CONFIG.maxAlertTextChars < 200 ||
  CONFIG.maxAlertTextChars > 3200
) {
  throw new Error('CONFIG.maxAlertTextChars must be an integer from 200 to 3200.');
}

const keywords = [...new Set(
  CONFIG.keywords
    .map((keyword) => String(keyword).trim())
    .filter(Boolean),
)];

return normalizedChannels.map((channel) => ({
  json: {
    ...CONFIG,
    channel,
    keywords: [...keywords],
    alertChatId,
  },
}));

/*
 * The HTTP Request node returns one full-response envelope per input channel.
 * This node reattaches the originating channel configuration using n8n's
 * paired-item link. Keeping the envelope is essential because a JSON [] body
 * would otherwise disappear as zero output items.
 */
const configurations = $('Configuration & Channels').all();

return $input.all().map((item, index) => {
  const pair = Array.isArray(item.pairedItem)
    ? item.pairedItem[0]
    : item.pairedItem;
  const sourceIndex = Number.isInteger(pair?.item) ? pair.item : index;
  const monitor = configurations[sourceIndex]?.json ?? configurations[index]?.json;

  if (!monitor) {
    throw new Error(`Could not restore configuration for Actor response item ${index}.`);
  }

  return {
    json: {
      ...item.json,
      _monitor: monitor,
    },
    pairedItem: { item: index },
  };
});

/*
 * Persistent monitoring engine.
 *
 * State is stored in n8n global workflow static data. n8n saves it only for
 * successful production executions of an active workflow; manual/editor runs
 * do not persist it. Keep executions serialized and let downstream alert
 * failures continue so the state commit can complete.
 */

const STATE_SCHEMA_VERSION = 1;
const now = new Date().toISOString();
const state = $getWorkflowStaticData('global');

if (state.schemaVersion === undefined) {
  state.schemaVersion = STATE_SCHEMA_VERSION;
  state.channels = {};
}

if (state.schemaVersion !== STATE_SCHEMA_VERSION) {
  throw new Error(
    `Unsupported monitor state schema ${state.schemaVersion}; expected ${STATE_SCHEMA_VERSION}. ` +
    'Do not reset state casually because that can replay old posts.',
  );
}

if (!state.channels || typeof state.channels !== 'object' || Array.isArray(state.channels)) {
  throw new Error('Monitor state is malformed: channels must be an object.');
}

function normalizeChannel(value) {
  return String(value ?? '').trim().replace(/^@/, '').toLowerCase();
}

function canonicalizeRanges(value) {
  if (!Array.isArray(value)) return [];

  const valid = value
    .filter((range) => (
      Array.isArray(range) &&
      range.length === 2 &&
      Number.isSafeInteger(range[0]) &&
      Number.isSafeInteger(range[1]) &&
      range[0] > 0 &&
      range[1] >= range[0]
    ))
    .map((range) => [range[0], range[1]])
    .sort((a, b) => a[0] - b[0] || a[1] - b[1]);

  const merged = [];
  for (const range of valid) {
    const previous = merged[merged.length - 1];
    if (!previous || range[0] > previous[1] + 1) {
      merged.push(range);
      continue;
    }
    previous[1] = Math.max(previous[1], range[1]);
  }
  return merged;
}

function isSeen(ranges, id) {
  let low = 0;
  let high = ranges.length - 1;
  while (low <= high) {
    const middle = Math.floor((low + high) / 2);
    const [start, end] = ranges[middle];
    if (id < start) high = middle - 1;
    else if (id > end) low = middle + 1;
    else return true;
  }
  return false;
}

function mergeIdsIntoRanges(ranges, ids) {
  return canonicalizeRanges([
    ...ranges,
    ...ids.map((id) => [id, id]),
  ]);
}

function filterMessage(row, monitor) {
  const text = typeof row.text === 'string' ? row.text : '';
  const keywords = (Array.isArray(monitor.keywords) ? monitor.keywords : [])
    .map((keyword) => String(keyword).trim())
    .filter(Boolean);
  const mode = monitor.keywordMode ?? 'any';

  if (mode === 'off' || keywords.length === 0) {
    return { matches: true, matchedKeywords: [] };
  }

  if (!text) {
    return { matches: false, matchedKeywords: [] };
  }

  const haystack = monitor.caseSensitive ? text : text.toLocaleLowerCase();
  const matchedKeywords = keywords.filter((keyword) => {
    const needle = monitor.caseSensitive ? keyword : keyword.toLocaleLowerCase();
    return haystack.includes(needle);
  });

  return {
    matches: mode === 'all'
      ? matchedKeywords.length === keywords.length
      : matchedKeywords.length > 0,
    matchedKeywords,
  };
}

function actorErrorSummary(channel, status, details, monitor) {
  return {
    json: {
      kind: 'status',
      channel,
      status,
      checkedAt: now,
      details,
      stateAdvanced: false,
      resultCount: 0,
      newCount: 0,
      alertCount: 0,
      windowSaturated: false,
      actorBuild: monitor?.actorBuild ?? null,
    },
  };
}

const alerts = [];
const summaries = [];

for (const inputItem of $input.all()) {
  const response = inputItem.json ?? {};
  const monitor = response._monitor ?? {};
  const channel = normalizeChannel(monitor.channel);

  if (!channel) {
    summaries.push(actorErrorSummary(
      '(unknown)',
      'PROTOCOL_ERROR',
      'Missing originating channel configuration.',
      monitor,
    ));
    continue;
  }

  if (response.error) {
    summaries.push(actorErrorSummary(
      channel,
      'ACTOR_REQUEST_ERROR',
      typeof response.error === 'string'
        ? response.error
        : (response.error.message ?? JSON.stringify(response.error)),
      monitor,
    ));
    continue;
  }

  const statusCode = Number(response.statusCode);
  if (!Number.isFinite(statusCode) || statusCode < 200 || statusCode >= 300) {
    summaries.push(actorErrorSummary(
      channel,
      'ACTOR_FAILED',
      `Apify returned HTTP ${Number.isFinite(statusCode) ? statusCode : 'unknown'}.`,
      monitor,
    ));
    continue;
  }

  let rows = response.body;
  if (typeof rows === 'string') {
    try {
      rows = JSON.parse(rows);
    } catch {
      rows = null;
    }
  }

  if (!Array.isArray(rows)) {
    summaries.push(actorErrorSummary(
      channel,
      'PROTOCOL_ERROR',
      'Expected the synchronous Actor endpoint to return a JSON array.',
      monitor,
    ));
    continue;
  }

  /*
   * An empty successful dataset is deliberately not used to initialize state.
   * If posts appear later, that later non-empty window becomes the safe
   * baseline instead of being emitted as a burst of "new" alerts.
   */
  if (rows.length === 0) {
    summaries.push(actorErrorSummary(
      channel,
      'EMPTY_RESULT',
      'No dataset rows were returned; channel baseline was left unchanged.',
      monitor,
    ));
    continue;
  }

  const byId = new Map();
  let invalidRowCount = 0;
  let duplicateRowCount = 0;

  for (const row of rows) {
    const id = Number(row?.id);
    const rowChannel = normalizeChannel(row?.channel);
    if (!Number.isSafeInteger(id) || id <= 0 || rowChannel !== channel) {
      invalidRowCount += 1;
      continue;
    }
    if (byId.has(id)) {
      duplicateRowCount += 1;
      continue;
    }
    byId.set(id, {
      channel,
      source_url: row.source_url ?? `https://t.me/s/${channel}`,
      scraped_at: row.scraped_at ?? null,
      id,
      url: row.url ?? `https://t.me/${channel}/${id}`,
      date: row.date ?? null,
      text: typeof row.text === 'string' ? row.text : null,
      views: row.views === null || row.views === undefined || row.views === ''
        ? null
        : (Number.isFinite(Number(row.views)) ? Number(row.views) : null),
      forwarded_from: row.forwarded_from ?? null,
      has_photo: row.has_photo === true,
      has_video: row.has_video === true,
      has_link_preview: row.has_link_preview === true,
    });
  }

  if (byId.size === 0) {
    summaries.push(actorErrorSummary(
      channel,
      'PROTOCOL_ERROR',
      `Dataset contained ${rows.length} row(s), but none matched the expected channel/ID contract.`,
      monitor,
    ));
    continue;
  }

  const uniqueRows = [...byId.values()].sort((a, b) => a.id - b.id);
  const prior = state.channels[channel];
  const firstSuccessfulRun = !prior?.initializedAt;
  const channelState = prior ?? {
    initializedAt: null,
    baselineFloorId: null,
    seenRanges: [],
    highestObservedId: null,
    totalProcessed: 0,
    totalAlertCandidates: 0,
  };

  const seenRanges = canonicalizeRanges(channelState.seenRanges);
  const minimumId = uniqueRows[0].id;
  const maximumId = uniqueRows[uniqueRows.length - 1].id;
  const baselineFloorId = firstSuccessfulRun
    ? minimumId
    : channelState.baselineFloorId;

  const observedUnseenIds = [];
  let alreadySeenCount = 0;
  let baselineSuppressedCount = 0;
  let historicalBackfillCount = 0;
  let filteredOutCount = 0;
  let eligibleNewCount = 0;
  let channelAlertCount = 0;

  for (const row of uniqueRows) {
    if (isSeen(seenRanges, row.id)) {
      alreadySeenCount += 1;
      continue;
    }

    observedUnseenIds.push(row.id);

    if (!firstSuccessfulRun && baselineFloorId !== null && row.id < baselineFloorId) {
      historicalBackfillCount += 1;
      continue;
    }

    if (firstSuccessfulRun && monitor.firstRunMode !== 'alert') {
      baselineSuppressedCount += 1;
      continue;
    }

    eligibleNewCount += 1;
    const filter = filterMessage(row, monitor);
    if (!filter.matches) {
      filteredOutCount += 1;
      continue;
    }

    channelAlertCount += 1;
    alerts.push({
      json: {
        kind: 'alert',
        channel,
        id: row.id,
        date: row.date,
        text: row.text,
        views: row.views,
        url: row.url,
        source_url: row.source_url,
        scraped_at: row.scraped_at,
        forwarded_from: row.forwarded_from,
        has_photo: row.has_photo,
        has_video: row.has_video,
        has_link_preview: row.has_link_preview,
        matchedKeywords: filter.matchedKeywords,
        alertChatId: monitor.alertChatId,
        maxAlertTextChars: monitor.maxAlertTextChars,
        actorBuild: monitor.actorBuild,
      },
    });
  }

  /*
   * Mark every valid observed ID before filtering. This gives at-most-once
   * behavior: changing keywords later will not replay posts already processed.
   */
  channelState.seenRanges = mergeIdsIntoRanges(seenRanges, observedUnseenIds);
  channelState.initializedAt = channelState.initializedAt ?? now;
  channelState.baselineFloorId = baselineFloorId;
  channelState.highestObservedId = Math.max(
    Number(channelState.highestObservedId) || 0,
    maximumId,
  );
  channelState.lastSuccessAt = now;
  channelState.lastResultCount = uniqueRows.length;
  channelState.lastNewCount = eligibleNewCount;
  channelState.lastAlertCount = channelAlertCount;
  channelState.totalProcessed = (Number(channelState.totalProcessed) || 0) + observedUnseenIds.length;
  channelState.totalAlertCandidates =
    (Number(channelState.totalAlertCandidates) || 0) + channelAlertCount;
  state.channels[channel] = channelState;

  /*
   * Use the raw response length for saturation detection. A full Actor window
   * can contain duplicate or invalid rows; deduplication must not hide the
   * possibility that older posts fell outside that window.
   */
  const windowSaturated = rows.length >= Number(monitor.limit);
  summaries.push({
    json: {
      kind: 'status',
      channel,
      status: firstSuccessfulRun
        ? (monitor.firstRunMode === 'alert' ? 'FIRST_RUN_ALERT_MODE' : 'BASELINE_CREATED')
        : (eligibleNewCount > 0 ? 'NEW_POSTS_PROCESSED' : 'NO_NEW_POSTS'),
      checkedAt: now,
      stateAdvanced: true,
      firstSuccessfulRun,
      resultCount: uniqueRows.length,
      rawRowCount: rows.length,
      invalidRowCount,
      duplicateRowCount,
      alreadySeenCount,
      observedUnseenCount: observedUnseenIds.length,
      newCount: eligibleNewCount,
      filteredOutCount,
      alertCount: channelAlertCount,
      baselineSuppressedCount,
      historicalBackfillCount,
      baselineFloorId,
      highestObservedId: channelState.highestObservedId,
      seenRanges: channelState.seenRanges,
      windowSaturated,
      warning: windowSaturated
        ? 'WINDOW_SATURATED: increase limit or run more frequently to avoid missing fast-moving posts.'
        : null,
      actorBuild: monitor.actorBuild,
    },
  });
}

alerts.sort((a, b) => (
  a.json.channel.localeCompare(b.json.channel) ||
  a.json.id - b.json.id
));
summaries.sort((a, b) => a.json.channel.localeCompare(b.json.channel));

state.lastCycleAt = now;
state.lastCycleSummary = summaries.map((item) => ({
  channel: item.json.channel,
  status: item.json.status,
  resultCount: item.json.resultCount,
  newCount: item.json.newCount,
  alertCount: item.json.alertCount,
}));

return [...alerts, ...summaries];

function mediaFallback(item) {
  const media = [];
  if (item.has_photo) media.push('photo');
  if (item.has_video) media.push('video');
  if (item.has_link_preview) media.push('link preview');
  return media.length > 0
    ? `[Media-only post: ${media.join(', ')}]`
    : '[Post has no text]';
}

function normalizeText(value) {
  return String(value ?? '')
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '');
}

/*
 * The Telegram node is configured for HTML parse mode. Escape all dynamic
 * values and truncate only between complete entities so arbitrary post text
 * cannot become markup or make Telegram reject an otherwise valid alert.
 */
function escapeHtmlWithin(value, maximum) {
  const source = [...normalizeText(value)];
  const max = Math.max(0, Math.floor(maximum));
  let output = '';

  for (let index = 0; index < source.length; index += 1) {
    const character = source[index];
    const escaped = character === '&'
      ? '&amp;'
      : (character === '<' ? '&lt;' : (character === '>' ? '&gt;' : character));
    const hasMore = index < source.length - 1;
    const available = Math.max(0, max - (hasMore ? 1 : 0));
    if (output.length + escaped.length > available) {
      return `${output.trimEnd()}…`;
    }
    output += escaped;
  }

  return output;
}

return $input.all().map((item, index) => {
  const alert = item.json;
  const requestedTextMaximum = Number(alert.maxAlertTextChars);
  const textMaximum = Number.isFinite(requestedTextMaximum)
    ? Math.min(3200, Math.max(200, Math.floor(requestedTextMaximum)))
    : 3000;
  const body = typeof alert.text === 'string' && alert.text.trim()
    ? alert.text.trim()
    : mediaFallback(alert);
  const views = alert.views === null || alert.views === undefined
    ? 'Unavailable'
    : Number(alert.views).toLocaleString('en-US');
  const date = escapeHtmlWithin(alert.date || 'Unavailable', 200);
  const channel = escapeHtmlWithin(alert.channel, 64);
  const messageId = escapeHtmlWithin(alert.id, 32);
  const keywordLine = Array.isArray(alert.matchedKeywords) && alert.matchedKeywords.length > 0
    ? `\nMatched: ${escapeHtmlWithin(alert.matchedKeywords.join(', '), 300)}`
    : '';

  const header = [
    '🚨 Telegram channel match',
    '',
    `Channel: @${channel}`,
    `Date: ${date}`,
    `Views: ${views}`,
    `Message ID: ${messageId}${keywordLine}`,
    '',
  ].join('\n');
  const postUrl = escapeHtmlWithin(
    alert.url || `https://t.me/${normalizeText(alert.channel)}/${normalizeText(alert.id)}`,
    256,
  );
  const footer = [
    '',
    'Original post:',
    postUrl,
  ].join('\n');
  const bodyBudget = Math.max(
    1,
    Math.min(textMaximum, 4000 - header.length - footer.length),
  );
  const alertText = `${header}${escapeHtmlWithin(body, bodyBudget)}${footer}`;

  return {
    json: {
      ...alert,
      alertText,
    },
    pairedItem: { item: index },
  };
});

const preparedAlerts = $('Format Telegram Alert').all();

return $input.all().map((item, index) => {
  const pair = Array.isArray(item.pairedItem)
    ? item.pairedItem[0]
    : item.pairedItem;
  const sourceIndex = Number.isInteger(pair?.item) ? pair.item : index;
  const alert = preparedAlerts[sourceIndex]?.json ?? preparedAlerts[index]?.json ?? {};
  const deliveryOk = item.json?.ok === true && !item.json?.error;

  return {
    json: {
      kind: 'delivery_result',
      channel: alert.channel ?? null,
      id: alert.id ?? null,
      url: alert.url ?? null,
      deliveryOk,
      telegramMessageId: deliveryOk
        ? (item.json?.result?.message_id ?? null)
        : null,
      deliveryError: deliveryOk
        ? null
        : (item.json?.error ?? 'Telegram did not return a confirmed success response.'),
      attemptedAt: new Date().toISOString(),
    },
    pairedItem: { item: index },
  };
});
